    <ul className="list list-movies">
      {movies?.map((movie) => (
        <Movie movie={movie} key={movie.imdbID} setSelectId={setSelectId} />
      ))}
    </ul>
  );
}

function Movie({ movie, setSelectId }) {
  return (
    <li onClick={() => setSelectId(movie.imdbID)}>
      <img src={movie.Poster} alt={`${movie.Title} poster`} />
      <h3>{movie.Title}</h3>
      <div>
        <p>
          <span>🗓</span>
          <span>{movie.Year}</span>
        </p>
      </div>
    </li>
  );
}

function SelectedMovie({ selectedId, handleCloseMovie }) {
  // fetch(`http://www.omdbapi.com/?apikey=${key}&i=${selectedId}`).then(
